PRAGMA foreign_keys = ON;
CREATE TABLE Users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE Stocks(code TEXT PRIMARY KEY,name TEXT NOT NULL,price REAL NOT NULL,change_pct REAL NOT NULL DEFAULT 0,category TEXT NOT NULL);
CREATE TABLE Accounts(user_id INTEGER PRIMARY KEY,cash REAL NOT NULL DEFAULT 100000,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES Users(id) ON DELETE CASCADE);
CREATE TABLE Holdings(user_id INTEGER NOT NULL,code TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 0,avg_cost REAL NOT NULL DEFAULT 0,PRIMARY KEY(user_id,code),FOREIGN KEY(user_id) REFERENCES Users(id) ON DELETE CASCADE,FOREIGN KEY(code) REFERENCES Stocks(code));
CREATE TABLE Orders(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,code TEXT NOT NULL,side TEXT NOT NULL,quantity INTEGER NOT NULL,price REAL NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES Users(id) ON DELETE CASCADE,FOREIGN KEY(code) REFERENCES Stocks(code));
CREATE TABLE Wallets(user_id INTEGER PRIMARY KEY,balance REAL NOT NULL DEFAULT 2000,FOREIGN KEY(user_id) REFERENCES Users(id) ON DELETE CASCADE);
CREATE TABLE PointBalances(user_id INTEGER PRIMARY KEY,points INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES Users(id) ON DELETE CASCADE);
CREATE TABLE Memberships(user_id INTEGER PRIMARY KEY,expires_at TEXT,FOREIGN KEY(user_id) REFERENCES Users(id) ON DELETE CASCADE);
CREATE TABLE RechargeOrders(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,item_type TEXT NOT NULL,item_name TEXT NOT NULL,wei_amount REAL NOT NULL,points_added INTEGER NOT NULL DEFAULT 0,member_days INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES Users(id) ON DELETE CASCADE);
CREATE TABLE MarketTicks(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT NOT NULL,price REAL NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(code) REFERENCES Stocks(code) ON DELETE CASCADE);
CREATE INDEX idx_market_ticks_code_id ON MarketTicks(code,id);
CREATE TABLE FishingDaily(user_id INTEGER NOT NULL,day TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,earned REAL NOT NULL DEFAULT 0,PRIMARY KEY(user_id,day),FOREIGN KEY(user_id) REFERENCES Users(id) ON DELETE CASCADE);
CREATE TABLE Sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL,expires_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES Users(id) ON DELETE CASCADE);
